<?php

/* @autogenerated */
declare(strict_types=1);

use PHPUnit\Framework\TestCase;
use Civi\Lughauth\Features\OAuth\DelegateLogin\Domain\DelegatedLoginEndpoint;
use Civi\Lughauth\Features\OAuth\DelegateLogin\Domain\DelegatedProviderDescription;
use Civi\Lughauth\Features\OAuth\DelegateLogin\Domain\DelegatedUserData;

final class DelegateLoginDomainUnitTest extends TestCase
{
    // --- DelegatedLoginEndpoint ---

    public function test_delegated_login_endpoint_stores_fields(): void
    {
        $ep = new DelegatedLoginEndpoint('GET', 'https://provider.example.com/authorize', ['scope' => 'openid']);

        $this->assertSame('GET', $ep->method);
        $this->assertSame('https://provider.example.com/authorize', $ep->url);
        $this->assertSame(['scope' => 'openid'], $ep->params);
    }

    public function test_delegated_login_endpoint_defaults_params_to_empty(): void
    {
        $ep = new DelegatedLoginEndpoint('POST', 'https://provider.example.com/token');

        $this->assertSame([], $ep->params);
    }

    // --- DelegatedProviderDescription ---

    public function test_delegated_provider_description_stores_fields(): void
    {
        $d = new DelegatedProviderDescription('google', 'Google', 'https://google.com/logo.png', true);

        $this->assertSame('google', $d->id);
        $this->assertSame('Google', $d->name);
        $this->assertSame('https://google.com/logo.png', $d->logo);
        $this->assertTrue($d->automatic);
    }

    public function test_delegated_provider_description_defaults_automatic_to_false(): void
    {
        $d = new DelegatedProviderDescription('github', 'GitHub', 'https://github.com/logo.png');

        $this->assertFalse($d->automatic);
    }

    // --- DelegatedUserData ---

    public function test_delegated_user_data_stores_required_fields(): void
    {
        $d = new DelegatedUserData(
            providerUserId: 'google-uid-123',
            email: 'alice@example.com',
        );

        $this->assertSame('google-uid-123', $d->providerUserId);
        $this->assertSame('alice@example.com', $d->email);
        $this->assertNull($d->name);
        $this->assertNull($d->givenName);
        $this->assertNull($d->familyName);
        $this->assertNull($d->pictureUrl);
        $this->assertFalse($d->emailVerified);
    }

    public function test_delegated_user_data_stores_optional_fields(): void
    {
        $d = new DelegatedUserData(
            providerUserId: 'uid',
            email: 'bob@example.com',
            name: 'Bob Smith',
            givenName: 'Bob',
            familyName: 'Smith',
            pictureUrl: 'https://cdn/pic.jpg',
            emailVerified: true,
        );

        $this->assertSame('Bob Smith', $d->name);
        $this->assertSame('Bob', $d->givenName);
        $this->assertSame('Smith', $d->familyName);
        $this->assertSame('https://cdn/pic.jpg', $d->pictureUrl);
        $this->assertTrue($d->emailVerified);
    }
}
